class Complex(ctypes.Structure):
    _fields_ = [('real', ctypes.c_double), ('imag', ctypes.c_double)]

def prime_factors(n, subtransforms=None):
    if not subtransforms:
        subtransforms = [1.0]
    factors = []
    while n > 1:
        for subtransform in subtransforms:
            if n % float(subtransform) == 0:
                factor = int(subtransform)
                factors.append(factor)
                n /= float(factor)
    return factors

def fft_factorize(n, subtransforms=None):
    libgslcblas.gsl_factorize.restype = ctypes.POINTER(Complex)
    libgslcblas.gsl_factorize.argtypes = [ctypes.c_double]
    result_ptr = libgslcblas.gsl_factorize(ctypes.c_double(n))
    result = []
    for i in range(result_ptr.contents.real):
        if abs(result_ptr[i].real) > 0.5:
            result.append(int(abs(float(result_ptr[i].real))))
    return prime_factors(n, subtransforms), len(result)

def main():
    n = int(input("Enter a positive integer: "))
    result, num_factors = fft_factorize(n)
    print(f"Prime factors: {result}", f"Number of factors: {num_factors}")

