def create_combination(n, k):
	from ctypes import CDLL
	dl = CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=CDLL.RTLD_GLOBAL)
gsl = CDLL("/usr/local/gsl/lib/libgsl.so")
	gsl_combination = dl.gsl_combination_alloc(n, k)
	if not gsl_combination:
		return None
	gsl.combination_init_first(gsl_combination, n, k)
	combination = [0] * k
	for i in range(k):
		combination[i] = int(dl.gsl_combination_get(gsl_combination, i))
	result = []
	for j in range(n-k+1):
		temp = combination[:]
		for k in range(k-1, -1, -1):
			combination[k] += 1
			for l in range(k):
				if combination[l] == n-j+l:
					break
			else:
					emp[k] = combination[l]
			temp[k-1:] = [0] * (k - 1)
			combination = temp[:]
		temp = []
		for i in range(k):
			temp.append(int(gsl.gsl_combination_get(gsl_combination, i)))
		result.append(temp)
	gsl.gsl_combination_free(gsl_combination)
	return result

