class gsl_permutation:
    def __init__(self):
        self.p = ctypes.c_int * 1
        self._ptr = ctypes.cast(ctypes.pointer(self.p()), ctypes.POINTER(ctypes.c_int))
    def __del__(self):
        if self._ptr:
            ctypes.c_free(self._ptr)

class gsl_vector:
    def __init__(self, shape):
        self.shape = tuple(shape)
