def permute_vector(perm: List[int], vec: List[float]) -> List[float]:
    if len(perm) != len(vec):
        raise ValueError('Permutation and vector lengths differ')

    p = gsl_permutation()
    v = gsl_vector((len(perm),))
    for i in range(len(perm)):
        p.p[0] = perm[i]
        v.data.fill(vec[i])

    f = ctypes.CFUNCTYPE(None, ctypes.POINTER(ctypes.c_int), ctypes.POINTER(ctypes.c_double)) 
    func_ptr = f(gsl.permute_vector)

    func_ptr(p._ptr, v.data.ctypes.data_as(ctypes.POINTER(ctypes.c_double)))

    return [float(x) for x in v.data.flatten()]

