def cblas_ccopy(N, X, incX, Y, incY):

    if not isinstance(N, int) or N <= 0:

        raise ValueError('N must be a positive integer')

    if not (isinstance(X, ctypes._ctypesLIB) and X._type.kind == ctypes._C_PTR):

        raise TypeError('X must be a ctypes array')

    if not isinstance(incX, int) or incX <= 0:

        raise ValueError('incX must be a positive integer')

    if not isinstance(Y, ctypes._ctypesLIB) and Y._type.kind == ctypes._C_PTR):

        raise TypeError('Y must be a ctypes array')

    if not isinstance(incY, int) or incY <= 0:

        raise ValueError('incY must be a positive integer')

    cblas_ccopy(N, X, incX, Y, incY)

