class wavedec_t(POINTER):
    pass

class wavelet_length_t(POINTER):
    pass

class data_array_t(POINTER):
    pass

_gsl_wavelet_init = None
_gsl_wavelet_alloc_desc = None
_gsl_wavelet_free_desc = None
_gsl_wavelet_cwt = None
_gsl_wavelet_iwt = None
_gsl_wavelet_destroy = None

gsl.wavedec.restype = wavedec_t
gsl.wavelet_length.restype = wavelet_length_t
gsl.data_array.restype = data_array_t

def load_data(file_path):
    with open(file_path, 'r') as file:
        return [float(line.strip()) for line in file.readlines()]

def gsl_wavelet_init():
    global _gsl_wavelet_init
    if not _gsl_wavelet_init:
        _gsl_wavelet_init = cdll('libgslcblas').gsl_wavelet_init
        _gsl_wavelet_init.restype = c_int

def gsl_wavelet_alloc_desc(length):
    global _gsl_wavelet_alloc_desc
    return _gsl_wavelet_alloc_desc(c_int(length))

def gsl_wavelet_free_desc(desc):
    global _gsl_wavelet_free_desc
    _gsl_wavelet_free_desc(POINTER(desc).contents)

def gsl_wavelet_cwt(data_array, desc):
    global _gsl_wavelet_cwt
    return _gsl_wavelet_cwt(data_array.contents, POINTER(desc).contents)

def gsl_wavelet_iwt(wavedec, desc):
    global _gsl_wavelet_iwt
    return _gsl_wavelet_iwt(POINTER(wavedec).contents, POINTER(desc).contents)

def gsl_wavelet_destroy(desc):
    global _gsl_wavelet_destroy
    _gsl_wavelet_destroy(POINTER(desc).contents)

def main(file_path):
    data = load_data(file_path)
    n = len(data)
    desc = gsl_wavelet_alloc_desc(n)
    wavedec = None

    try:
        gsl_wavelet_init()
        wavedec = gsl_wavelet_cwt((data_array_t * (c_double * n))(data), desc)
        result = [None] * n
        for i in range(0, n):
            if abs(data[i]) < 0.5:
                result[i] = 0.0
            else:
                result[i] = data[i]

        inverse_result = gsl_wavelet_iwt((wavedec_t * (c_double * n))(result), desc)
    finally:
        if wavedec:
            gsl_wavelet_free_desc(desc)
        if inverse_result:
            gsl_wavelet_destroy(desc)

    original_data = [round(x, 2) for x in data]
    transformed_data = [round(x, 2) for x in result]
    print('Original:\n' + '\n'.join(map(str, zip(original_data, inverse_result))))
    print('\nTransformed:\n' + '\n'.join(map(str, zip(original_data, result))))

