def compute_integration(m, n):
    # Create a GSLFunction instance with m as the power of x and an array of coefficients
    func = GSLFunction(np.poly1d([1] + [0]*(m-1)).coeffs[::-1])

    # Initialize result arrays for actual and expected results
    actual_result = np.zeros(n)
    expected_result = np.zeros(n)

    for i in range(n):
        x = (i+1)/n
