gsl_cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)

class gsl_vector(ctypes.Structure):
    _fields_ = [('data', ctypes.POINTER(ctypes.c_double)),
               ('size', ctypes.c_int)]

def create_gsl_vector(data):
    vec = gsl_vector()
    vec.data = ctypes.cast((ctypes.c_double * len(data))(*data), ctypes.POINTER(ctypes.c_double))
    vec.size = len(data)
    return vec

def extract_gsl_vector(vec, size):
    data = (ctypes.c_double * size)()
    for i in range(size):
        data[i] = vec.data[i]
    return [i for i in data]

def gsl_filter_impulse_python(input_data, t, K):
    input_len = len(input_data)

    if not isinstance(t, float):
        raise ValueError("Threshold 't' must be a floating-point number.")

    if not isinstance(K, int) or K < 1:
        raise ValueError("Workspace size 'K' must be an integer greater than zero.")

    if input_len <= 0:
        return [], 0

    try:
        gsl_filter_impulse = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so").gsl_filter_impulse
        gsl_filter_impulse_alloc = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL).gsl_filter_impulse_alloc
        gsl_filter_impulse_free = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL).gsl_filter_impulse_free

        filter_workspace = gsl_filter_impulse_alloc(K, K)

        output_data = [0.0] * input_len
        for i in range(input_len):
            output_data[i] = float(gsl_filter_impulse(filter_workspace, ctypes.c_double(input_data[i]), t))

