            raise ValueError('xrange is not increasing')
    for i in range(1,ny):
        if yrange[i] <= yrange[i-1]:
            raise ValueError('yrange is not increasing')

    libgsl.gsl_histogram2d_alloc.restype = POINTER(GSL_Histogram2D)
